import{_ as s,H as a,f as p,i as l}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"07｜实操课：顶层设计全流程演示","description":"","frontmatter":{},"headers":[{"level":2,"title":"我的真实体验和看法","slug":"我的真实体验和看法","link":"#我的真实体验和看法","children":[]},{"level":2,"title":"顶层设计全流程实操","slug":"顶层设计全流程实操","link":"#顶层设计全流程实操","children":[{"level":3,"title":"场景一：产品定义","slug":"场景一-产品定义","link":"#场景一-产品定义","children":[]},{"level":3,"title":"场景二：应用架构设计","slug":"场景二-应用架构设计","link":"#场景二-应用架构设计","children":[]},{"level":3,"title":"场景三：部署架构与数据设计","slug":"场景三-部署架构与数据设计","link":"#场景三-部署架构与数据设计","children":[]},{"level":3,"title":"场景四：Claude Code 实战技巧","slug":"场景四-claude-code-实战技巧","link":"#场景四-claude-code-实战技巧","children":[]}]},{"level":2,"title":"生成的 Claude.md","slug":"生成的-claude-md","link":"#生成的-claude-md","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/07｜实操课：顶层设计全流程演示.md","filePath":"ClaudeCode企业级全链路开发实战/07｜实操课：顶层设计全流程演示.md","lastUpdated":1779815375000}'),e={name:"ClaudeCode企业级全链路开发实战/07｜实操课：顶层设计全流程演示.md"};function i(t,n,c,o,d,r){return a(),p("div",null,[...n[0]||(n[0]=[l(`<h1 id="_07-实操课-顶层设计全流程演示" tabindex="-1">07｜实操课：顶层设计全流程演示 <a class="header-anchor" href="#_07-实操课-顶层设计全流程演示" aria-label="Permalink to &quot;07｜实操课：顶层设计全流程演示&quot;">​</a></h1><p>你好，我是 Robert。</p><p>这是我们第一节实操课，核心目的就是展示Claude Code在本章节的真实操作过程，让你对其使用方法有一个更为直观和透彻的了解。</p><p>本节实操课将以文字+视频的方式进行，主要包含两部分：</p><ul><li><p>第一部分是用文稿呈现我自己真实使用AI Coding的体验和看法，不是教程，是我自己的落地感受。同时也会回答下课程里大家比较感兴趣的几个问题。</p></li><li><p>第二部分是用录屏呈现顶层设计的完整实操过程，分为四个场景。这部分也会有参考文稿，不过更多细节会在视频里呈现，建议大家优先去观看视频。</p></li></ul><h2 id="我的真实体验和看法" tabindex="-1">我的真实体验和看法 <a class="header-anchor" href="#我的真实体验和看法" aria-label="Permalink to &quot;我的真实体验和看法&quot;">​</a></h2><p>目前就我个人而言，离开Claude Code，我的生产力会严重下降。可能出乎你的意料，我是一个编码量特别大的人，但我跟Claude Code的协作，代码只是一部分。</p><p>这里总结一下我的哪些工作会交给Claude Code完成，具体如下：</p><ul><li><p><strong>让它给我做页面</strong>。我的开源项目需要运营管理平台，需要官网主页。我不擅长前端，开源社区找前端也非常麻烦。有了Claude Code后，这部分全部搞定。而且效果超级好，设计、风格、页面组成我都很满意。</p></li><li><p><strong>让它给我写文档</strong>。我的流程一般是，我会跟Claude Code讨论某个观点。比如AI Agent通信，当前是怎么做的，有什么痛点，业界是怎样的，我会输出我的看法，然后让它给我整理成文章。</p></li><li><p><strong>让它给我做市场调研</strong>。因为它有很多信息，比如最近我在研究AI Agent之间的通信，我会让它给我讲讲当前实际有什么问题，最新的AI Infra公司有在做类似的事情吗，当前的痛点是什么，各自的解决方案是什么。</p></li><li><p><strong>让它给我做角色推演</strong>。我针对AI Agent通信的痛点出了一个开源方案。然后我让它站在资深基础架构师、一线开发工程师、算法工程师、Agent自己（OpenClaw）的角度，发表看法。目的是获得各个角色的视角，避免自己技术自嗨，闭门造车。</p></li><li><p><strong>跟它讨论技术方案</strong>。我会偶尔跟它讨论技术方案，但频率不高。可能我自己搞开发比较久，很多架构设计的事情我都有自己看法，它最多验证，我不会纯听它的。因为它总是给出看起来对、但是没那么适合我的方案。</p></li><li><p><strong>跟它协作写代码</strong>。这是最主要的部分（可能也没那么多）。我自己比较保守，有点代码洁癖，所以我会区分项目的重要程度，确定跟它的合作深度。某些项目让它全部完成，某些项目只让它写部分。</p></li><li><p><strong>让它给我当翻译</strong>。我的开源项目的官网英文文档，都是让它生成的，特别快。一句话：帮我生成这份文档的英文版。</p></li><li><p><strong>闲聊</strong>。哈哈，这点其实蛮重要的。时不时会有一些idea，我会快速问它的看法，让它发表观点，效率特别高。</p></li></ul><p>我还用Claude Code做了好多事情，如果你感兴趣，我们可以在评论区讨论，或者大家特别有兴趣的话题，我可以在课程中做加餐。</p><p>下面我主要展开三个方面。</p><p><strong>1. AI 协助做前端页面</strong></p><p>我用AI协助搭建了开源项目的产品官网。我不是前端工程师，但AI让我能独立完成这些工作：帮我快速出页面、跟我探讨产品定位和文案措辞、做竞品和业界方案的调研。AI在这个场景里的角色是协作者，不是执行者。后面的课程，也会分享哪些地方AI帮了大忙，哪些地方它给的东西不能直接用，必须自己判断。</p><p><strong>2. 老项目改造</strong></p><p>公司内部有一套SDK和Web项目，跑了很久，代码量大，架构固定。我尝试用AI Coding来做改造。老项目意味着既有代码、既有架构、既有约束，AI不是从白纸开始，而是要在已有的框架里工作。给AI做好约束，以小任务执行为主。完整理解项目很难，先让AI通过小任务慢慢理解，上下文多了，就会越做越好。后面的课程中，我们也会分享哪些任务AI做得好、哪些地方它爱添乱、上下文长度和代码理解力的边界在哪，了解这些也会有帮助。</p><p><strong>3. 新项目全部用 AI Coding 写</strong></p><p>公司内部一个基于ZooKeeper的网关项目，从第一行代码开始就是纯AI Coding实现的。不是玩具项目，上线后承接了不小的流量，运行良好，至今没出过问题。这是跟老项目改造完全不同的体验，从零开始，你可以用SDD的方式定义规范，让AI在你设计的框架里工作。后面的课程中，我会分享新项目全程AI Coding的效率、质量、踩过的坑，以及“人定规范、AI写代码”这个协作模式在生产环境的真实验证。</p><h2 id="顶层设计全流程实操" tabindex="-1">顶层设计全流程实操 <a class="header-anchor" href="#顶层设计全流程实操" aria-label="Permalink to &quot;顶层设计全流程实操&quot;">​</a></h2><p>这部分我们会用完整的屏录演示，让你看到真实的操作过程：我给了什么指令、Claude Code回了什么、我怎么判断和追问、最终怎么定稿。</p><h3 id="场景一-产品定义" tabindex="-1">场景一：产品定义 <a class="header-anchor" href="#场景一-产品定义" aria-label="Permalink to &quot;场景一：产品定义&quot;">​</a></h3><p>目标：从梳理 Dify 功能全景到确定 Hify 的功能范围和技术栈。展示三问裁剪法的实际运用，以及你和 Claude Code 之间“它建议、你判断”的真实过程。</p><h4 id="第一步-梳理-dify-功能全景" tabindex="-1">第一步：梳理 Dify 功能全景 <a class="header-anchor" href="#第一步-梳理-dify-功能全景" aria-label="Permalink to &quot;第一步：梳理 Dify 功能全景&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我梳理 Dify（https://dify.ai）这个产品的核心功能模块，</span></span>
<span class="line"><span>按类别分组，每个模块用一两句话说明它做什么。</span></span></code></pre></div><p>要点：</p><ul><li><p>Claude Code几秒钟给出八大模块的结构化清单</p></li><li><p>我拿它的输出和Dify官方文档对了一遍，修正了过时描述，补了MCP协议支持</p></li><li><p>强调“AI 加速信息收集，但你要验证”</p></li></ul><h4 id="第二步-功能取舍" tabindex="-1">第二步：功能取舍 <a class="header-anchor" href="#第二步-功能取舍" aria-label="Permalink to &quot;第二步：功能取舍&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要基于 Dify 做一个简化版的 AI Agent 平台，叫 Hify。</span></span>
<span class="line"><span>约束条件：一个人开发，面向团队内部 20-50 人使用，本地部署。</span></span>
<span class="line"><span>请从刚才梳理的功能列表中，帮我判断哪些是必须做的核心功能，</span></span>
<span class="line"><span>哪些可以砍掉，给出每个的理由。</span></span></code></pre></div><p>要点：</p><ul><li><p>Claude Code给了三档分类（必须做 / 降级简化 / 砍掉），这个分档方式本身就有价值</p></li><li><p>重点展示RAG的判断，它建议保留，理由是“内部部署区别于ChatGPT的核心价值”。我被说服了，但降级：一期只支持TXT</p></li><li><p>展示我否决权限体系的过程，50人团队不需要</p></li><li><p>用三问裁剪法过一遍最终决策</p></li></ul><h4 id="第三步-技术选型" tabindex="-1">第三步：技术选型 <a class="header-anchor" href="#第三步-技术选型" aria-label="Permalink to &quot;第三步：技术选型&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 是一个 AI Agent 开发平台，一个人开发，本地部署，目标 20-50 人使用。</span></span>
<span class="line"><span>帮我对比以下技术方案的优劣：</span></span>
<span class="line"><span>1) Spring Boot + Vue  2) Go + React  3) Python FastAPI + React</span></span>
<span class="line"><span>重点考虑开发效率、生态成熟度、AI 领域 SDK 支持、运维复杂度。</span></span></code></pre></div><p>追问指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个人做企业级后端，Spring Boot 和 FastAPI 在工程化能力上差距有多大？</span></span></code></pre></div><p>要点：</p><ul><li>Claude Code推荐FastAPI，还给了“Java + Python 混合”的折中方案</li><li>我否决了混合方案，一个人维护两套技术栈是灾难</li><li>最终选Spring Boot：AI生态劣势存在，但工程化和技术栈统一性优先</li></ul><h3 id="场景二-应用架构设计" tabindex="-1">场景二：应用架构设计 <a class="header-anchor" href="#场景二-应用架构设计" aria-label="Permalink to &quot;场景二：应用架构设计&quot;">​</a></h3><p>目标：确定模块化单体架构、Spring代码组织规范、外部调用处理方案。展示和Claude Code的追问挑战过程。</p><h4 id="第一步-应用架构选型" tabindex="-1">第一步：应用架构选型 <a class="header-anchor" href="#第一步-应用架构选型" aria-label="Permalink to &quot;第一步：应用架构选型&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 是一个 Spring Boot 单体应用，功能包括模型提供商管理、Agent 配置、</span></span>
<span class="line"><span>对话引擎、知识库 RAG、简版工作流、MCP 工具接入。一个人开发，一期 50 人使用，</span></span>
<span class="line"><span>但后续可能要扩到几千人。代码内部怎么组织？给我方案对比。</span></span></code></pre></div><p>追问指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个人维护六七个微服务，每个要独立部署、独立配置、独立监控，</span></span>
<span class="line"><span>精力消耗会不会太大</span></span></code></pre></div><p>要点：</p><ul><li>Claude Code给了 3 个方案，推荐微服务</li><li>我用“一个人维护太重”这个现实约束否决，选模块化单体</li><li>展示最终的Maven模块划分（七个业务模块 + common）</li></ul><h4 id="第二步-代码组织规范" tabindex="-1">第二步：代码组织规范 <a class="header-anchor" href="#第二步-代码组织规范" aria-label="Permalink to &quot;第二步：代码组织规范&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 是模块化单体，用 Spring Boot + MyBatis-Plus。帮我定义代码组织规范，</span></span>
<span class="line"><span>覆盖：每个模块内部的分层结构、每一层的职责边界、跨模块调用的规则。</span></span>
<span class="line"><span>要求具体到 AI 能直接执行，不要模糊的描述。</span></span></code></pre></div><p>要点：</p><ul><li>强调“这些规范是给 AI 写的，不是给人写的”</li><li>Controller只做参数校验、跨模块走Service接口，人凭习惯知道，AI不知道</li><li>展示规范写进CLAUDE.md的过程</li></ul><h4 id="第三步-外部调用设计" tabindex="-1">第三步：外部调用设计 <a class="header-anchor" href="#第三步-外部调用设计" aria-label="Permalink to &quot;第三步：外部调用设计&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 要调用多个外部 LLM API（OpenAI、Claude、Gemini、Ollama），</span></span>
<span class="line"><span>这些调用慢且不稳定。从线程管理、容错、超时、重试四个维度，给出完整的技术方案。</span></span></code></pre></div><p>追问指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>流式响应用 SSE，Spring MVC 怎么处理？需不需要引入 WebFlux？</span></span></code></pre></div><p>要点：</p><ul><li><p>Claude Code建议WebFlux，我否决，不增加技术栈复杂度</p></li><li><p>SseEmitter + 独立线程池 + 120秒超时，50人够用</p></li><li><p>展示线程池隔离、熔断、超时、重试的完整方案写进CLAUDE.md</p></li></ul><h3 id="场景三-部署架构与数据设计" tabindex="-1">场景三：部署架构与数据设计 <a class="header-anchor" href="#场景三-部署架构与数据设计" aria-label="Permalink to &quot;场景三：部署架构与数据设计&quot;">​</a></h3><p>目标：设计当前部署架构、预判性能瓶颈、规划扩展路径、定义数据模型和数据库规范。</p><h4 id="第一步-当前部署架构" tabindex="-1">第一步：当前部署架构 <a class="header-anchor" href="#第一步-当前部署架构" aria-label="Permalink to &quot;第一步：当前部署架构&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 是模块化单体，技术栈 Spring Boot + Vue + MySQL + Redis + pgvector。</span></span>
<span class="line"><span>目标 50 人内部使用，生产环境用 Docker + K8s 部署。</span></span>
<span class="line"><span>帮我设计当前阶段的部署架构：有哪些组件、请求怎么流转、每个组件的职责是什么。</span></span></code></pre></div><p>要点：</p><ul><li>Claude Code给了组件职责表 + “当前做 vs 暂时跳过”对比表</li><li>重点展示“暂时跳过”的判断——单副本够用、MQ是过度设计、不需要链路追踪</li></ul><h4 id="第二步-性能瓶颈预判" tabindex="-1">第二步：性能瓶颈预判 <a class="header-anchor" href="#第二步-性能瓶颈预判" aria-label="Permalink to &quot;第二步：性能瓶颈预判&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于 Hify 当前的部署架构，帮我分析：这个系统的性能瓶颈可能在哪？</span></span>
<span class="line"><span>按严重程度排序，每个瓶颈给出触发条件和一期是否需要处理。</span></span></code></pre></div><p>要点：</p><ul><li>Claude Code给了7个瓶颈的排序表，结论是“一期只做两件事”</li><li>这张表就是你的系统软肋地图，现在不处理但心里有数</li><li>大部分工程师不会提前想这个，Claude Code帮你几分钟画出来</li></ul><h4 id="第三步-数据库规范" tabindex="-1">第三步：数据库规范 <a class="header-anchor" href="#第三步-数据库规范" aria-label="Permalink to &quot;第三步：数据库规范&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 用 MySQL 8.x + pgvector。帮我定义数据库层面的性能规范，</span></span>
<span class="line"><span>覆盖：索引设计原则、大表预判和应对策略、分页查询注意事项、通用字段约定。</span></span>
<span class="line"><span>要求具体到 AI 建表时能直接执行。</span></span></code></pre></div><p>要点：</p><ul><li>展示Claude Code给的五条索引规则（带正反例代码）</li><li>重点展示“逻辑删除字段必须加进索引”和“游标分页”，这些不写进规范AI就不会遵守</li><li>展示pgvector HNSW索引规范</li></ul><h3 id="场景四-claude-code-实战技巧" tabindex="-1">场景四：Claude Code 实战技巧 <a class="header-anchor" href="#场景四-claude-code-实战技巧" aria-label="Permalink to &quot;场景四：Claude Code 实战技巧&quot;">​</a></h3><p>目标：演示compact/clear的实际操作效果、用业界规范喂Claude Code生成CLAUDE.md、review修改过程。</p><h4 id="第一步-compact-和-clear-演示" tabindex="-1">第一步：compact 和 clear 演示 <a class="header-anchor" href="#第一步-compact-和-clear-演示" aria-label="Permalink to &quot;第一步：compact 和 clear 演示&quot;">​</a></h4><p>操作：</p><ul><li>展示一个对话已经很长的场景（前面几个场景的对话累积）</li><li>输入 /compact，展示压缩前后的上下文变化</li><li>输入 /clear，展示清空后 CLAUDE.md 自动加载的效果</li><li>新对话里输入一条简单指令，验证Claude Code还知道项目规范</li></ul><p>要点：</p><ul><li>每个任务完成后commit + clear是最佳实践</li><li>CLAUDE.md自动加载，项目规范不丢</li><li>compact适合任务中途上下文快满了，clear适合切换任务</li></ul><h4 id="第二步-业界规范喂入" tabindex="-1">第二步：业界规范喂入 <a class="header-anchor" href="#第二步-业界规范喂入" aria-label="Permalink to &quot;第二步：业界规范喂入&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在做一个 Spring Boot 项目，请基于阿里巴巴 Java 开发手册，</span></span>
<span class="line"><span>帮我提炼出最关键的 20 条编码规范，写成 CLAUDE.md 可以直接用的格式。</span></span>
<span class="line"><span>重点覆盖命名、异常处理、日志、并发这几个方面。</span></span>
<span class="line"><span>不要照搬原文，要精简到 AI 能直接执行。</span></span></code></pre></div><p>要点：</p><ul><li>Claude Code几分钟生成精简版，不是照搬原文而是提炼关键条目</li><li>你不需要读完几十页规范，让AI消化后帮你提炼</li><li>展示review过程：删掉不适用的条目、调整措辞</li></ul><h4 id="第三步-生成完整-claude-md" tabindex="-1">第三步：生成完整 CLAUDE.md <a class="header-anchor" href="#第三步-生成完整-claude-md" aria-label="Permalink to &quot;第三步：生成完整 CLAUDE.md&quot;">​</a></h4><p>指令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以下是 Hify 项目前期做的所有决策：[贴上所有片段]</span></span>
<span class="line"><span>另外请基于阿里巴巴 Java 开发手册，补充编码规范部分。</span></span>
<span class="line"><span>请帮我合并生成一份完整的 CLAUDE.md。</span></span></code></pre></div><p>要点：</p><ul><li>展示Claude Code合并后的完整版（滚动浏览）</li><li>指出3处需要人工修改的地方：行为指令措辞太软、“不做什么”有遗漏、多了不必要的logback配置</li><li>修改定稿后commit</li><li>到这里CLAUDE.md完整版就位，Claude Code对Hify的全部认知就绪</li></ul><h2 id="生成的-claude-md" tabindex="-1">生成的 Claude.md <a class="header-anchor" href="#生成的-claude-md" aria-label="Permalink to &quot;生成的 Claude.md&quot;">​</a></h2><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Hify 项目开发规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 项目概览</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hify 是一个简化版内部 AI Agent 平台，基于 Dify 思路设计。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **团队规模**：1 人开发，20-50 人内部使用，本地部署</span></span>
<span class="line"><span>- **技术栈**：Spring Boot + MyBatis-Plus + Vue + MySQL 8.x + Redis + pgvector</span></span>
<span class="line"><span>- **架构模式**：模块化单体（Modular Monolith），代码边界清晰，可平滑拆分为微服务</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 核心功能模块（MVP 范围）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 模块 | 说明 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| 模型管理 (model) | 管理 OpenAI / Claude / Gemini / Ollama 等 LLM 提供商配置，支持连通性测试 |</span></span>
<span class="line"><span>| Agent 配置 (agent) | 配置 Agent 名称、系统提示词、绑定模型、关联知识库和 MCP 工具 |</span></span>
<span class="line"><span>| 对话引擎 (conversation) | 多轮对话、历史记录、SSE 流式响应 |</span></span>
<span class="line"><span>| 知识库 RAG (knowledge) | 文档上传 → 异步向量化 → pgvector 余弦搜索 → 注入 LLM 上下文 |</span></span>
<span class="line"><span>| 简版工作流 (workflow) | 顺序节点执行：开始 → LLM → 条件分支 → 工具调用 → 结束 |</span></span>
<span class="line"><span>| MCP 工具接入 (mcp) | 接入外部 MCP 工具，供 Agent 和工作流调用 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**砍掉的功能**：多租户、自定义插件市场、实时协作、企业 SSO、精细化权限控制、数据集版本管理。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 代码组织规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 包结构</span></span>
<span class="line"><span></span></span>
<span class="line"><span>com.hify</span></span>
<span class="line"><span>├── common/</span></span>
<span class="line"><span>│   ├── config/          # MybatisPlusConfig, JacksonConfig, AsyncConfig, ThreadPoolConfig</span></span>
<span class="line"><span>│   ├── exception/       # BizException, ErrorCode, GlobalExceptionHandler</span></span>
<span class="line"><span>│   ├── web/             # Result&amp;lt;T&amp;gt;, PageResult&amp;lt;T&amp;gt;</span></span>
<span class="line"><span>│   └── util/            # JsonUtil, DateUtil</span></span>
<span class="line"><span>├── modules/</span></span>
<span class="line"><span>│   ├── model/           # LLM 提供商管理</span></span>
<span class="line"><span>│   ├── agent/           # Agent 配置</span></span>
<span class="line"><span>│   ├── conversation/    # 对话引擎</span></span>
<span class="line"><span>│   ├── knowledge/       # 知识库 RAG</span></span>
<span class="line"><span>│   ├── workflow/        # 简版工作流</span></span>
<span class="line"><span>│   └── mcp/             # MCP 工具接入</span></span>
<span class="line"><span>└── HifyApplication.java</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个模块内部四层结构：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>modules/{module}/</span></span>
<span class="line"><span>├── api/       # 对外暴露的接口（interface），供其他模块调用</span></span>
<span class="line"><span>├── domain/    # 业务逻辑：Service 实现、领域对象、Factory、Repository 接口</span></span>
<span class="line"><span>├── infra/     # 基础设施：Mapper、RepositoryImpl、外部 API 客户端、config</span></span>
<span class="line"><span>└── web/       # Controller，只处理 HTTP 层</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 各层职责边界</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 层 | 职责 | 禁止 |</span></span>
<span class="line"><span>|----|------|------|</span></span>
<span class="line"><span>| web/ | 接收请求、参数校验（&amp;#64;Valid）、调用本模块 api/ 接口、返回 Result&amp;lt;T&amp;gt; | 直接调用其他模块 domain/、直接操作数据库 |</span></span>
<span class="line"><span>| api/ | 定义跨模块调用的 interface 和 DTO | 包含业务逻辑实现 |</span></span>
<span class="line"><span>| domain/ | 业务逻辑、领域对象、事务边界（&amp;#64;Transactional） | 直接依赖 Mapper、依赖 web 层 |</span></span>
<span class="line"><span>| infra/ | Mapper、RepositoryImpl（PO ↔ 领域对象转换）、外部调用 | 包含业务逻辑 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 跨模块调用规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **只能**通过目标模块的 \`api/\` 接口调用，禁止直接 import 其他模块的 \`domain/\` 或 \`infra/\` 类</span></span>
<span class="line"><span>- 跨模块传递使用 \`api/\` 包下定义的 DTO，不传递 PO 或领域对象</span></span>
<span class="line"><span>- 循环依赖视为架构错误，立即重构</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`java</span></span>
<span class="line"><span>// 正确：agent 模块通过 ModelService（api/ 接口）调用 model 模块</span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>@RequiredArgsConstructor</span></span>
<span class="line"><span>public class AgentServiceImpl implements AgentService {</span></span>
<span class="line"><span>    private final ModelService modelService; // 来自 model 模块的 api/ 接口</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## LLM 调用规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 线程池配置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`java</span></span>
<span class="line"><span>// llm-pool: 非流式调用（阻塞等待完整响应）</span></span>
<span class="line"><span>@Bean(&quot;llmExecutor&quot;)</span></span>
<span class="line"><span>public ThreadPoolExecutor llmExecutor() {</span></span>
<span class="line"><span>    return new ThreadPoolExecutor(20, 50, 60L, TimeUnit.SECONDS,</span></span>
<span class="line"><span>        new LinkedBlockingQueue&amp;lt;&gt;(100),</span></span>
<span class="line"><span>        new ThreadFactoryBuilder().setNameFormat(&quot;llm-pool-%d&quot;).setDaemon(true).build(),</span></span>
<span class="line"><span>        new ThreadPoolExecutor.CallerRunsPolicy()  // 满载时调用方线程执行，不丢任务</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// llm-stream: 流式 SSE 调用（长连接）</span></span>
<span class="line"><span>@Bean(&quot;llmStreamExecutor&quot;)</span></span>
<span class="line"><span>public ThreadPoolExecutor llmStreamExecutor() {</span></span>
<span class="line"><span>    return new ThreadPoolExecutor(30, 80, 60L, TimeUnit.SECONDS,</span></span>
<span class="line"><span>        new LinkedBlockingQueue&amp;lt;&gt;(50),</span></span>
<span class="line"><span>        new ThreadFactoryBuilder().setNameFormat(&quot;llm-stream-%d&quot;).setDaemon(true).build(),</span></span>
<span class="line"><span>        new AbortPolicy()  // 流式超限直接拒绝，由上层返回 503</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### OkHttpClient 配置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`java</span></span>
<span class="line"><span>// 非流式：有 readTimeout</span></span>
<span class="line"><span>@Bean(&quot;standardLlmClient&quot;)</span></span>
<span class="line"><span>public OkHttpClient standardLlmClient() {</span></span>
<span class="line"><span>    return new OkHttpClient.Builder()</span></span>
<span class="line"><span>        .connectTimeout(5, TimeUnit.SECONDS)</span></span>
<span class="line"><span>        .readTimeout(120, TimeUnit.SECONDS)</span></span>
<span class="line"><span>        .writeTimeout(30, TimeUnit.SECONDS)</span></span>
<span class="line"><span>        .connectionPool(new ConnectionPool(20, 5, TimeUnit.MINUTES))</span></span>
<span class="line"><span>        .addInterceptor(new LoggingInterceptor())</span></span>
<span class="line"><span>        .build();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 流式：readTimeout 设为 0（SSE 不能有读超时）</span></span>
<span class="line"><span>@Bean(&quot;streamLlmClient&quot;)</span></span>
<span class="line"><span>public OkHttpClient streamLlmClient() {</span></span>
<span class="line"><span>    return new OkHttpClient.Builder()</span></span>
<span class="line"><span>        .connectTimeout(5, TimeUnit.SECONDS)</span></span>
<span class="line"><span>        .readTimeout(0, TimeUnit.SECONDS)</span></span>
<span class="line"><span>        .writeTimeout(30, TimeUnit.SECONDS)</span></span>
<span class="line"><span>        .build();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 超时层次（三层保护）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. OkHttp connectTimeout = 5s（TCP 握手超时）</span></span>
<span class="line"><span>2. OkHttp readTimeout = 120s（单次读取超时，仅非流式）</span></span>
<span class="line"><span>3. CompletableFuture.get(90, TimeUnit.SECONDS)（总体超时兜底）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 重试策略（Resilience4j）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 普通 LLM：最多 3 次，初始等待 500ms，指数退避 2x，最大等待 10s</span></span>
<span class="line"><span>- Ollama（本地）：最多 5 次，初始等待 2s</span></span>
<span class="line"><span>- 仅对网络异常和 5xx 重试，4xx（参数错误）不重试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 熔断器配置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`yaml</span></span>
<span class="line"><span># COUNT_BASED 滑动窗口，20 次请求内失败率 &gt;50% 触发熔断</span></span>
<span class="line"><span># 慢调用（&gt;30s）超过 80% 也触发熔断</span></span>
<span class="line"><span># 熔断后等待 30s 进入 half-open，放行 5 次探测</span></span>
<span class="line"><span>failure-rate-threshold: 50</span></span>
<span class="line"><span>slow-call-duration-threshold: 30s</span></span>
<span class="line"><span>slow-call-rate-threshold: 80</span></span>
<span class="line"><span>wait-duration-in-open-state: 30s</span></span>
<span class="line"><span>permitted-calls-in-half-open-state: 5</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Fallback 路由</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`yaml</span></span>
<span class="line"><span>hify.llm.fallback:</span></span>
<span class="line"><span>  openai: ollama</span></span>
<span class="line"><span>  claude: openai</span></span>
<span class="line"><span>  gemini: ollama</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主 Provider 熔断或异常时自动切换 fallback，fallback 失败则抛出 BizException。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 部署架构</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户浏览器</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Ingress Nginx（L7 负载均衡 + SSL 终止 + SSE 支持）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├──▶ hify-frontend（Vue SPA，Nginx 静态文件服务，2 副本）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └──▶ hify-backend（Spring Boot，2 副本）</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ├──▶ MySQL 8.x（主数据存储）</span></span>
<span class="line"><span>              ├──▶ Redis（Session / 缓存 / 限流）</span></span>
<span class="line"><span>              └──▶ PostgreSQL + pgvector（向量存储）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Ingress 关键配置（SSE 必须）**：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`yaml</span></span>
<span class="line"><span>nginx.ingress.kubernetes.io/proxy-read-timeout: &quot;300&quot;</span></span>
<span class="line"><span>nginx.ingress.kubernetes.io/proxy-buffering: &quot;off&quot;</span></span>
<span class="line"><span>nginx.ingress.kubernetes.io/limit-rps: &quot;20&quot;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Backend 容器规格**：requests 512Mi/250m，limits 1Gi/1000m，replicas=2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**JVM 启动参数**：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`dockerfile</span></span>
<span class="line"><span>ENTRYPOINT [&quot;java&quot;, &quot;-XX:MaxRAMPercentage=75.0&quot;, &quot;-XX:+UseG1GC&quot;,</span></span>
<span class="line"><span>            &quot;-Djava.security.egd=file:/dev/./urandom&quot;, &quot;-jar&quot;, &quot;app.jar&quot;]</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 数据库规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### MySQL 通用字段约定</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每张表必须包含以下字段：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`sql</span></span>
<span class="line"><span>id          BIGINT          NOT NULL AUTO_INCREMENT,  -- 主键，禁用 UUID</span></span>
<span class="line"><span>created_at  DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),</span></span>
<span class="line"><span>updated_at  DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),</span></span>
<span class="line"><span>deleted     TINYINT(1)      NOT NULL DEFAULT 0,       -- 逻辑删除标志</span></span>
<span class="line"><span>PRIMARY KEY (id)</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 字符集：\`utf8mb4\`，排序规则：\`utf8mb4_unicode_ci\`</span></span>
<span class="line"><span>- 禁用 \`VARCHAR\` 无长度约束，text 类 content 字段用 \`MEDIUMTEXT\`</span></span>
<span class="line"><span>- 金额用 \`DECIMAL(19,4)\`，禁用 \`FLOAT/DOUBLE\`</span></span>
<span class="line"><span>- 布尔用 \`TINYINT(1)\`，不用 \`BIT\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 索引设计原则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **区分度低的字段不单独建索引**（如 deleted、status 枚举），必须与高区分度字段组合</span></span>
<span class="line"><span>2. **组合索引遵循最左前缀**：等值查询字段在左，范围查询字段在右</span></span>
<span class="line"><span>3. **查询条件中含 \`deleted\`**，必须将 \`deleted\` 纳入索引</span></span>
<span class="line"><span>4. **每表索引不超过 5 个**（含主键），写多读少的表控制在 3 个以内</span></span>
<span class="line"><span>5. **禁止在 \`TEXT/BLOB\` 类型字段上建普通索引**，需要时建前缀索引或全文索引</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`sql</span></span>
<span class="line"><span>-- 正确示例：conversation_id 高区分度在左，deleted 次之，created_at 范围在右</span></span>
<span class="line"><span>INDEX idx_conv_created (conversation_id, deleted, created_at)</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 大表处理策略</span></span>
<span class="line"><span></span></span>
<span class="line"><span>判断为大表的阈值：行数 &amp;gt; 500 万 或 数据量 &amp;gt; 2GB</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 场景 | 策略 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| t_message | 按 conversation_id 分区，或按月归档冷数据 |</span></span>
<span class="line"><span>| 知识库向量表 | ivfflat 索引，lists = sqrt(行数) |</span></span>
<span class="line"><span>| 日志类表 | 只保留 90 天，定期 DELETE + OPTIMIZE TABLE |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 分页查询规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **禁止** \`LIMIT offset, size\` 深分页（offset &amp;gt; 1000 全表扫描）</span></span>
<span class="line"><span>- 对话记录类使用**游标分页**：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`sql</span></span>
<span class="line"><span>SELECT id, role, content, created_at FROM t_message</span></span>
<span class="line"><span>WHERE conversation_id = ?</span></span>
<span class="line"><span>  AND deleted = 0</span></span>
<span class="line"><span>  AND (created_at &amp;lt; ? OR (created_at = ? AND id &amp;lt; ?))</span></span>
<span class="line"><span>ORDER BY created_at DESC, id DESC</span></span>
<span class="line"><span>LIMIT 20;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 管理后台必须分页时，用 \`WHERE id &amp;gt; lastId LIMIT size\` 替代 offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### pgvector 索引规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`sql</span></span>
<span class="line"><span>-- 余弦相似度索引，lists 值 = sqrt(总行数)，行数 &amp;lt;10 万时 lists=100</span></span>
<span class="line"><span>CREATE INDEX idx_embedding_ivfflat ON knowledge_embedding</span></span>
<span class="line"><span>USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查询时设置 probes，精度和速度平衡</span></span>
<span class="line"><span>SET ivfflat.probes = 10;</span></span>
<span class="line"><span>SELECT * FROM knowledge_embedding</span></span>
<span class="line"><span>ORDER BY embedding &amp;lt;=&gt; &#39;[...]&#39;::vector LIMIT 5;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 索引检测措施</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**开发阶段**：启用 p6spy，拦截执行 &amp;gt;10ms 的查询自动 EXPLAIN，type=ALL 时打印警告日志。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**CI 阶段**：关键查询写 \`IndexCoverageTest\`，EXPLAIN 结果中 type=ALL 则测试失败，阻断合并。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**生产阶段**：定期查询 \`performance_schema.events_statements_summary_by_digest\`，找出 \`sum_no_index_used &amp;gt; 0\` 的 SQL。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`sql</span></span>
<span class="line"><span>SELECT digest_text, count_star AS 执行次数, sum_no_index_used AS 未用索引次数</span></span>
<span class="line"><span>FROM performance_schema.events_statements_summary_by_digest</span></span>
<span class="line"><span>WHERE sum_no_index_used &gt; 0</span></span>
<span class="line"><span>ORDER BY sum_no_index_used DESC LIMIT 20;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 编码规范（基于阿里巴巴 Java 开发手册）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 命名</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **类名用 UpperCamelCase**，方法名、变量名用 lowerCamelCase，常量用 UPPER_SNAKE_CASE，包名全小写无下划线。</span></span>
<span class="line"><span>2. **禁止用拼音或拼音缩写**命名，禁止单字母变量（循环变量 \`i/j/k\` 除外）。</span></span>
<span class="line"><span>3. **方法名体现动词**：查询用 \`get/list/query\`，修改用 \`update\`，删除用 \`delete/remove\`，新增用 \`create/add\`，布尔返回值用 \`is/has/can\`。</span></span>
<span class="line"><span>4. **Service 接口不加 I 前缀**，实现类加 \`Impl\` 后缀（\`AgentService\` + \`AgentServiceImpl\`）。</span></span>
<span class="line"><span>5. **数据库表名用 \`t_\` 前缀**，列名用 snake_case；PO 类用 \`Po\` 后缀，DTO 用 \`Dto\`/\`Request\`/\`Response\`，Mapper 用 \`Mapper\` 后缀。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 异常处理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. **禁止 catch 后 \`e.printStackTrace()\` 或空 catch**，必须记录日志或向上抛出。</span></span>
<span class="line"><span>7. **业务异常统一抛 \`BizException(ErrorCode)\`**，不用 RuntimeException 传递业务语义。</span></span>
<span class="line"><span>8. **只在顶层（GlobalExceptionHandler）处理并转换为 HTTP 响应**，中间层不捕获再包装。</span></span>
<span class="line"><span>9. **finally 块不写 return**，不在 finally 中抛出新异常（会吞掉原始异常）。</span></span>
<span class="line"><span>10. **NPE 防御**：方法返回值优先返回空集合（\`Collections.emptyList()\`）而非 null，接口入参用 \`&amp;#64;NonNull\`/\`&amp;#64;Valid\` 注解声明约束。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 日志</span></span>
<span class="line"><span></span></span>
<span class="line"><span>11. **使用 SLF4J 接口 + Logback 实现**，类中用 \`&amp;#64;Slf4j\`（Lombok），禁止用 \`System.out.println\`。</span></span>
<span class="line"><span>12. **禁止在循环体内打日志**，高频路径只在异常分支记录。</span></span>
<span class="line"><span>13. **占位符格式 \`log.info(&quot;xxx {}&quot;, var)\`**，禁止字符串拼接（避免无效 toString 开销）。</span></span>
<span class="line"><span>14. **日志分级约定**：DEBUG=详细调试，INFO=关键业务节点，WARN=可恢复异常或配置缺失，ERROR=需人工介入的故障。生产环境 INFO 级别，日志文件按天滚动，保留 30 天。</span></span>
<span class="line"><span>15. **LLM 调用必须记录**：provider、model、耗时、token 数、是否命中缓存，便于成本分析。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 并发</span></span>
<span class="line"><span></span></span>
<span class="line"><span>16. **线程池必须显式创建**（\`ThreadPoolExecutor\`），禁止用 \`Executors.newFixedThreadPool\`（无界队列 OOM）。</span></span>
<span class="line"><span>17. **ThreadLocal 用完必须 \`remove()\`**，防止线程池场景下数据泄漏。</span></span>
<span class="line"><span>18. **加锁粒度最小化**：只锁共享变量操作，不锁 I/O 和 LLM 调用；优先用 \`ReentrantLock\` 替代 \`synchronized\`（可设超时）。</span></span>
<span class="line"><span>19. **单例 Bean 的成员变量必须是线程安全的**：无状态 Service 天然安全；有状态则用 \`ThreadLocal\` 或局部变量，禁止用实例变量存请求上下文。</span></span>
<span class="line"><span>20. **\`CompletableFuture\` 异步调用必须指定线程池**（\`supplyAsync(task, llmExecutor)\`），禁止用默认 \`ForkJoinPool.commonPool()\`（会影响其他异步任务）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 性能瓶颈优先级（一期处理清单）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 级别 | 瓶颈 | 一期处理方式 |</span></span>
<span class="line"><span>|------|------|-------------|</span></span>
<span class="line"><span>| P0 | LLM API 延迟高（3-30s） | 线程隔离 + 熔断 + Fallback（已设计） |</span></span>
<span class="line"><span>| P0 | 向量检索无索引全表扫描 | 建 ivfflat 索引（建表时必须创建） |</span></span>
<span class="line"><span>| P1 | 对话消息深分页 | 游标分页（禁止 LIMIT offset） |</span></span>
<span class="line"><span>| P1 | N+1 查询 | MyBatis-Plus 批量查询，禁止循环单查 |</span></span>
<span class="line"><span>| P2 | 连接池耗尽 | HikariCP 配置：maximumPoolSize=20，connectionTimeout=3000ms |</span></span>
<span class="line"><span>| 延后 | 静态资源未压缩 | Nginx gzip，流量大时处理 |</span></span>
<span class="line"><span>| 延后 | JVM GC 停顿 | G1GC 已启用，暂不调优 |</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>两部分内容讲完，顶层设计篇正式结束。</p><p>第一部分，不只是几个场景的体验分享，更重要的是让你看到 AI Coding 的使用面远比“写代码”宽。做页面、写文档、市场调研、角色推演、技术讨论、翻译、闲聊……它是一个全方位的协作者。但它在不同场景下的表现差异很大，关键是你怎么用。</p><p>第二部分，四个场景走完，回顾一下你手上现在有什么：</p><ul><li><p>一份完整的产品定义（做什么、不做什么、做到什么程度）</p></li><li><p>一套应用架构（模块划分、代码组织规范、外部调用处理）</p></li><li><p>一套系统架构（部署形态、性能瓶颈地图、三阶段扩展路径、数据库规范）</p></li><li><p>一份完整的 CLAUDE.md。</p></li></ul><p>到这，我们没写一行业务代码，但所有决策都已经落成文字。从下一讲开始，Claude Code 就会在这些约束下写代码，它会清楚地知道：模块怎么分、代码放哪里、接口什么格式、索引怎么建、什么不能做。这就是 SDD 的威力，规范定得越清楚，后面写代码越快越稳。</p><p>期待你与我分享自己的使用体验。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,102)])])}const m=s(e,[["render",i]]);export{h as __pageData,m as default};
